import manifest from '@/content/images.json';

export type ImageName = Exclude<keyof typeof manifest, 'spr-logo'>;

type Entry = { width: number; height: number; widths: number[] };
const data = manifest as Record<string, Entry>;

/** Responsive WebP sources generated by scripts/build-images.mjs */
export function imageSet(name: ImageName) {
  const entry = data[name];
  const largest = entry.widths[entry.widths.length - 1];
  return {
    src: `/images/${name}-${largest}.webp`,
    srcSet: entry.widths.map(w => `/images/${name}-${w}.webp ${w}w`).join(', '),
    width: entry.width,
    height: entry.height,
  };
}

export const logo = {
  src: '/images/spr-logo-240.webp',
  srcSet: '/images/spr-logo-240.webp 1x, /images/spr-logo-480.webp 2x',
  width: data['spr-logo'].width,
  height: data['spr-logo'].height,
};
